use rvn_graph::*;
use std::{fs,path::PathBuf};
fn directory(name:&str)->PathBuf{let root=PathBuf::from(std::env::var("RVN_NATIVE_SOURCE_TEST_DIR").expect("private fixture root required")).join(format!("auto-{name}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir_all(&root).unwrap();root}
fn wire(g:&mut GraphDocument,a:NodeId,ak:&str,b:NodeId,bk:&str){g.connect(g.pin_by_key(a,ak).unwrap().id,g.pin_by_key(b,bk).unwrap().id).unwrap();}
#[test]
fn automatic_regular_link_open_and_transpile_preserve_real_native_source_ids(){
 let root=directory("cold");let source=include_str!("fixtures/native_source_single.rvn");fs::write(root.join("main.rvn"),source).unwrap();let workspace=SourceWorkspace::link(&root,&root.join("main.rvn"),&[]).unwrap();let g=workspace.project().graphs().iter().find(|g|g.graph_id==GraphId::new(900)).unwrap();assert!(transpile_with_origins(g).unwrap().source.contains("inspect \"n3:"));let cold=SourceWorkspace::open(&root).unwrap().unwrap();assert_eq!(cold.project().graphs(),workspace.project().graphs());assert_eq!(fs::read_to_string(root.join("main.rvn")).unwrap(),source);assert_eq!(native_source_sites(&cold.freeze_native_program().unwrap()).unwrap().len(),1);
}
#[test]
fn automatic_new_editor_inspector_preserves_old_node_contract_and_old_scene_source(){
 let root=directory("mixed");let source="// old source remains authoritative\nfunction probe(){return [__rvn_text_table_valid(__rvn_string_table_text_name(__rvn_literal_name(\"asset:Table\"),\"hello\")),false]}\nlabel start\nset result=probe()\n\"Old scene remains separate\"\njump untouched\nlabel untouched\n\"Untouched legacy\"\nreturn\n";fs::write(root.join("main.rvn"),source).unwrap();let mut workspace=SourceWorkspace::link(&root,&root.join("main.rvn"),&[]).unwrap();let mut graphs=workspace.project().graphs().to_vec();let unchanged=graphs.iter().find(|g|matches!(&g.kind,GraphKind::Label{name}if name=="untouched")).unwrap().clone();
 let g=graphs.iter_mut().find(|g|matches!(&g.kind,GraphKind::Function{name}if name=="probe")).unwrap();let legacy=g.nodes.values().find(|n|n.kind==NodeKind::GetStringTableIdAndKey).unwrap().id;assert_eq!(g.nodes[&legacy].inspector_contract,Some(InspectorEvaluationContract::LegacyStateless));let text=g.pin_by_key(legacy,"text").unwrap().id;let from=g.edges.values().find(|e|e.input==text).unwrap().output;let list=g.nodes.values().find(|n|n.kind==NodeKind::ListLiteral).unwrap().id;let item=g.pin_by_key(list,"item_1").unwrap().id;let old=g.edges.values().find(|e|e.input==item).map(|e|g.pins[&e.output].node);
 let native=g.add_catalog_node(NodeKind::GetStringTableIdAndKey,[600.,0.]).unwrap();g.connect(from,g.pin_by_key(native,"text").unwrap().id).unwrap();wire(g,native,"valid",list,"item_1");if let Some(old)=old{g.remove_node(old);}
 assert_eq!(g.nodes[&legacy].inspector_contract,Some(InspectorEvaluationContract::LegacyStateless));assert_eq!(g.nodes[&native].inspector_contract,Some(InspectorEvaluationContract::NativeFrameV1));let id=g.graph_id;let nodes=g.nodes.keys().copied().collect::<Vec<_>>();let compiled=transpile_with_origins(g).unwrap();assert!(compiled.source.contains("__rvn_text_table_valid("));assert_eq!(compiled.source.matches("inspect \"").count(),1);
 workspace.save(&graphs).unwrap();let saved=fs::read_to_string(root.join("main.rvn")).unwrap();assert!(saved.contains("Old scene remains separate"));assert!(saved.contains("label untouched\n\"Untouched legacy\"\nreturn"));assert!(!root.join("graphs/RVN").exists());let cold=SourceWorkspace::open(&root).unwrap().unwrap();let actual=cold.project().graphs().iter().find(|g|g.graph_id==id).unwrap();assert_eq!(actual.nodes.keys().copied().collect::<Vec<_>>(),nodes);assert_eq!(actual.nodes[&legacy].inspector_contract,Some(InspectorEvaluationContract::LegacyStateless));assert_eq!(actual.nodes[&native].inspector_contract,Some(InspectorEvaluationContract::NativeFrameV1));assert_eq!(cold.project().graphs().iter().find(|g|g.kind==unchanged.kind).unwrap(),&unchanged);
 let start=cold.project().graphs().iter().find(|g|matches!(&g.kind,GraphKind::Label{name}if name=="start")).unwrap();let target=start.nodes.values().find(|n|n.kind==NodeKind::LabelValue).unwrap();assert_eq!(target.properties.get("label"),Some(&PropertyValue::String("untouched".into())));assert!(transpile(start).unwrap().source.contains("jump untouched"));
}
#[test]
fn automatic_mixed_reimport_keeps_empty_init_as_derived_view_and_rejects_cached_declarations(){
 let script=rvn_parser::parse(include_str!("fixtures/native_source_single.rvn")).unwrap();let mut previous=import_script(&rvn_parser::parse("label start\nset result=1\n").unwrap()).unwrap();let init=previous.iter_mut().find(|g|g.kind==GraphKind::Init).unwrap();let id=init.graph_id;init.variables.insert("injected_cache".into(),VariableDefinition{name:"injected_cache".into(),value_type:ValueType::Int,default_value:PropertyValue::Int(777)});
 let imported=reimport_native_frame_script(&script,&previous).unwrap();let init=imported.iter().find(|g|g.kind==GraphKind::Init).unwrap();assert_eq!(init.graph_id,id);assert!(!init.variables.contains_key("injected_cache"));assert!(init.edges.is_empty());assert!(init.nodes.values().all(|node|node.kind==NodeKind::Init));assert!(native_source_sites(&rvn_parser::parse_program(include_str!("fixtures/native_source_single.rvn")).unwrap()).is_err(),"Graph freeze needs actual source paths, no fabricated Init origin");
}
#[test]
fn automatic_source_writer_cas_refuses_changed_disk_before_source_or_cache_publication(){
 let root=directory("cas");let source=include_str!("fixtures/native_source_single.rvn");fs::write(root.join("main.rvn"),source).unwrap();let mut workspace=SourceWorkspace::link(&root,&root.join("main.rvn"),&[]).unwrap();let graphs=workspace.project().graphs().to_vec();let sidecar=fs::read(root.join(".rvn-authoring.json")).unwrap();let changed=format!("{source}// external change\n");fs::write(root.join("main.rvn"),&changed).unwrap();assert!(workspace.save(&graphs).is_err());assert_eq!(fs::read_to_string(root.join("main.rvn")).unwrap(),changed);assert_eq!(fs::read(root.join(".rvn-authoring.json")).unwrap(),sidecar);
}

#[test]
fn automatic_native_recovery_is_explicit_and_stale_recovery_never_changes_source(){
 let root=directory("recovery");let source=include_str!("fixtures/native_source_single.rvn");fs::write(root.join("main.rvn"),source).unwrap();let mut workspace=SourceWorkspace::link(&root,&root.join("main.rvn"),&[]).unwrap();let mut graphs=workspace.project().graphs().to_vec();graphs.iter_mut().find(|g|g.graph_id==GraphId::new(900)).unwrap().set_pin_default(NodeId::new(2),"key",PropertyValue::String("explicit recovery 🌍".into())).unwrap();workspace.write_recovery(&graphs).unwrap();let receipt=workspace.freeze_native_program().unwrap();assert_eq!(receipt.sources[0].source,source);assert_eq!(fs::read_to_string(root.join("main.rvn")).unwrap(),source);
 let mut cold=SourceWorkspace::open(&root).unwrap().unwrap();assert_eq!(cold.recovery().unwrap().as_ref(),Some(&graphs));assert_eq!(cold.freeze_native_program().unwrap(),receipt);cold.save(&graphs).unwrap();assert!(cold.recovery().unwrap().is_none());assert!(fs::read_to_string(root.join("main.rvn")).unwrap().contains("explicit recovery"));
 let saved=fs::read_to_string(root.join("main.rvn")).unwrap();cold.write_recovery(&graphs).unwrap();let cache=fs::read(root.join(".rvn-authoring.recovery.json")).unwrap();let external=format!("{saved}// actual external revision\n");fs::write(root.join("main.rvn"),&external).unwrap();assert!(cold.recovery().is_err());assert!(cold.save(&graphs).is_err());assert_eq!(fs::read_to_string(root.join("main.rvn")).unwrap(),external);assert_eq!(fs::read(root.join(".rvn-authoring.recovery.json")).unwrap(),cache);
}
